      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C))."
          ],
          "claim_ids": ["N002"],
          "rationale": "Claim N002 faithfully retains the requirement to document material discrepancies by submitting one or more of the listed documents, preserving choice logic without requiring every document category.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "(a) Name change orders; or",
            "(b) Divorce decrees;",
            "(2) Certificates of naturalization;",
            "(3) Marriage certificates;",
            "(4) Documentation demonstrating change of name by operation of state law; or",
            "(5) Documentation of customary usage."
          ],
          "claim_ids": ["N002"],
          "rationale": "Claim N002 preserves all six leaf options in alternative_quotes and choice_text as acceptable documentation options.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "(1) Court orders or decrees:",
            "(a) Name change orders; or",
            "(b) Divorce decrees;"
          ],
          "claim_ids": ["N002"],
          "rationale": "Claim N002 faithfully retains the court orders or decrees parent category along with its name change order and divorce decree alternatives.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "(see an exception for married names in 8 FAM 403.1-4(C))"
          ],
          "claim_ids": ["N002"],
          "rationale": "The married-name exception cross-reference is retained in references and context_quotes as an explicit remote reference without assuming all married applicants are exempt.",
          "status": "pass"
        },
        {
          "index": 4,
          "source_quotes": [
            "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
          ],
          "claim_ids": ["N002"],
          "rationale": "Claim N002 includes 22 CFR 51.25 in its cited references and quote as the governing basis for acceptable documentation means.",
          "status": "pass"
        }
      ],
      "negative_controls": [
        {
          "index": 0,
          "source_quotes": [
            "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C))."
          ],
          "claim_ids": ["N002"],
          "rationale": "Defective and should be flagged. The synthetic negative control requires the applicant to submit all listed documents conjunctively, whereas the source specifies documentation by submission of one or more of the listed documents.",
          "status": "fail"
        }
      ],
      "uncertainty": "none"
    },
    {
      "id": "NREG-02",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name. If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;"
          ],
          "claim_ids": ["N008"],
          "rationale": "Claim N008 retains the parent condition of a material name change occurring more than one year before DS-11 application with unchanged ID as inherited scope.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;"
          ],
          "claim_ids": ["N008"],
          "rationale": "Claim N008 explicitly requires insufficient time to request submission of acceptable ID prior to urgent or emergency travel, rather than travel urgency alone.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
